MERGE `{{params.project_name}}.semantics_central.CarTransitJobs` final
USING (
{{range_query}}
) staging
ON final.transit_job_id = staging.transit_job_id
WHEN MATCHED THEN
UPDATE SET
final.internal_id = staging.internal_id,
final.country_id = staging.country_id,
final.start_place = staging.start_place,
final.end_place = staging.end_place,
final.start_mileage = staging.start_mileage,
final.end_mileage = staging.end_mileage,
final.driver_name = staging.driver_name,
final.driver_id = staging.driver_id,
final.driver_company = staging.driver_company,
final.start_date = staging.start_date,
final.end_date = staging.end_date,
final.created_at = staging.created_at,
final.created_by_id = staging.created_by_id,
final.created_by_name = staging.created_by_name,
final.updated_at = staging.updated_at,
final.updated_by_id = staging.updated_by_id,
final.updated_by_name = staging.updated_by_name,
final.deleted_at = staging.deleted_at,
final.deleted_by_id = staging.deleted_by_id,
final.deleted_by_name = staging.deleted_by_name, 
final.checkin_at = staging.checkin_at,
final.checkin_by_id = staging.checkin_by_id,
final.checkin_by_name = staging.checkin_by_name, 
final.checkout_at = staging.checkout_at,
final.checkout_by_id = staging.checkout_by_id,
final.checkout_by_name = staging.checkout_by_name, 
final.transit_type = staging.transit_type,
final.transit_job_status = staging.transit_job_status,
final.transit_job_comment = staging.transit_job_comment,
final.pending_cars = staging.pending_cars
WHEN NOT MATCHED THEN
INSERT (
    transit_job_id,
    internal_id,
    country_id,
    start_place,
    end_place,
    start_mileage,
    end_mileage,
    driver_name,
    driver_id,
    driver_company,
    start_date,
    end_date,
    created_at,
    created_by_id,
    created_by_name,
    updated_at,
    updated_by_id,
    updated_by_name,
    deleted_at,
    deleted_by_id,
    deleted_by_name, 
    checkin_at,
    checkin_by_id,
    checkin_by_name, 
    checkout_at,
    checkout_by_id,
    checkout_by_name, 
    transit_type,
    transit_job_status,
    transit_job_comment,
    pending_cars
) VALUES (
staging.transit_job_id,
staging.internal_id,
staging.country_id,
staging.start_place,
staging.end_place,
staging.start_mileage,
staging.end_mileage,
staging.driver_name,
staging.driver_id,
staging.driver_company,
staging.start_date,
staging.end_date,
staging.created_at,
staging.created_by_id,
staging.created_by_name,
staging.updated_at,
staging.updated_by_id,
staging.updated_by_name,
staging.deleted_at,
staging.deleted_by_id,
staging.deleted_by_name, 
staging.checkin_at,
staging.checkin_by_id,
staging.checkin_by_name, 
staging.checkout_at,
staging.checkout_by_id,
staging.checkout_by_name, 
staging.transit_type,
staging.transit_job_status,
staging.transit_job_comment,
staging.pending_cars
)